pub fn lost_permutation(b: Vec<u32>, m: usize, s: u32) -> bool {
    let n = m + (s as usize);
    let mut missing_sum = s;
    let mut present = vec![false; n + 1];
    for &x in &b {
        if x as usize <= n {
            present[x as usize] = true;
        }
    }

    let mut missing = Vec::new();
    for i in 1..=n {
        if !present[i] {
            missing.push(i as u32);
        }
    }

    if missing.iter().sum::<u32>() != s {
        return false;
    }

    let mut combined = b.clone();
    combined.extend(missing);
    combined.sort();

    let mut seen = vec![false; n + 1];
    for &x in &combined {
        if x as usize <= n && seen[x as usize] {
            return false;
        }
        if x as usize <= n {
            seen[x as usize] = true;
        }
    }

    for i in 1..=n {
        if !seen[i] {
            return false;
        }
    }

    true
}
